{
  "packet_id": "H6-T04-2",
  "claim_id": "C031",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C031.main",
    "value": "A continuous history supports attributing the examined publication to the tracked account.",
    "scope": "A supportive identity inference, not proof that identity linkage is correct.",
    "provenance": {
      "refs": [
        {"source_id": "P017", "role": "SUPPORT"},
        {"source_id": "P021", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 supplies the account attribution; P021 explicitly limits what continuity establishes about identity linkage."
    }
  },
  "signal_basis": {
    "component_id": "C031.signal_basis",
    "value": "Events linked using account and schedule identifiers, with schedule lineage checked, form an internally consistent sequence connecting account creation through preparation and draft versions to publication; reported offline activity remains distinguished from logged events.",
    "scope": "The bounded cohort's examined histories. These are proposed observations, assumed to occur for this judgment.",
    "provenance": {
      "refs": [
        {"source_id": "P002", "role": "SUPPORT"},
        {"source_id": "P012", "role": "SUPPORT"},
        {"source_id": "P016", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply identifier and lineage checks, the continuity signal, its evidence distinctions and its prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C031.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this bounded supportive identity inference."
    }
  },
  "rationale": "Checked identifier links and a consistent history connecting creation to publication provide evidence for account attribution. The claim requires support rather than conclusive identity verification, so the operation and assumed signal license it within its explicit limit.",
  "uncertainty": "Consistent records may still contain false reports or incorrect identity links; continuity does not establish their correctness.",
  "anomalies": []
}
